func TestPeerReceiptDelegationSignsOnlyPlannedPeers(t *testing.T) {
	fixture := newSeedCLIFixture(t)
	peerPublic, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
