func customerOpenFixture(t *testing.T) (string, string, string, string, managedmaterial.InitialSpec,
	customerPreparationReply, customerOpenSigningKeys,
) {
	t.Helper()
	directory := t.TempDir()
	now := time.Now().UTC().Truncate(time.Second)
	recipient, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	_, recipientSigner, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	controllerPublic, controllerPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	catalog, err := managedmaterial.InitialCatalog("1G000000000000000000000001", nil)
	if err != nil {
		t.Fatal(err)
	}
	spec := managedmaterial.InitialSpec{
		PlacementDatabaseID: "0000000000JJVVW9EMWY1PE1VX", PartitionID: "0000000000Z3WK359G2W66CVT8",
		Scope: managedmaterial.AuthorityScope{ClusterID: "0102030405060708090a0b0c0d0e0f10",
			TenantID:   "0G000000000000000000000001",
			DatabaseID: "10000000000000000000000001", ShardID: 7, Epoch: 1},
		LiveS3: managedmaterial.LiveS3Target{Bucket: "alpha-live", Region: "sa-saopaulo-1",
			Endpoint:   "https://alpha.compat.objectstorage.sa-saopaulo-1.oci.customer-oci.com",
			Credential: oci.SecretVersionReference{SecretOCID: "ocid1.vaultsecret.oc1.sa-saopaulo-1.alpha", VersionNumber: 3}},
		Catalogs: []managedmaterial.InitialCatalogInput{{CollectionID: catalog.CollectionID, CanonicalCatalog: catalog.Bytes}},
		Members: [2]managedmaterial.InitialMember{
			{SeatID: "000000000082AXF7GZQT1D126Y", MemberID: "20000000000000000000000001",
				Incarnation: "01010101010101010101010101010101", ServerName: "a.replication.example",
				FailureDomain: "FAULT-DOMAIN-1", MaterialDirectory: "/var/lib/terrabase/attempt-a/material",
				ReplicationIP: "10.0.0.11", ReplicationPort: 9443, ClientIP: "10.0.0.11", ClientPort: 9465},
			{SeatID: "0000000000XG8SBD7XGE97V28G", MemberID: "20000000000000000000000002",
				Incarnation: "02020202020202020202020202020202", ServerName: "b.replication.example",
				FailureDomain: "FAULT-DOMAIN-2", MaterialDirectory: "/var/lib/terrabase/attempt-b/material",
				ReplicationIP: "10.0.0.12", ReplicationPort: 9443, ClientIP: "10.0.0.12", ClientPort: 9465},
		},
		Recipient: managedmaterial.RecipientGrant{PublicKey: recipient.PublicKey().Bytes(), ExpiresAt: now.Add(time.Hour)},
	}
	spec.Recipient.Signature = ed25519.Sign(recipientSigner, managedmaterial.RecipientGrantMessage(spec))
	bundle, err := managedmaterial.GenerateInitial(spec, recipientSigner.Public().(ed25519.PublicKey), now)
	if err != nil {
		t.Fatal(err)
	}
	specWire, err := protocol.EncodeJSON(spec)
	if err != nil {
		t.Fatal(err)
	}
	specDigest := sha256.Sum256(specWire)
	specSHA := hex.EncodeToString(specDigest[:])
	object := managedmaterial.ObjectReference{
		Name:      "material/v2/gru/" + spec.PlacementDatabaseID + "/" + spec.PartitionID + "/g1-" + specSHA + ".json",
		VersionID: "version-1", ETag: "etag-1", SHA256: strings.Repeat("a", 64), SpecSHA256: specSHA,
	}
	receipt, err := managedmaterial.SignPreparationReceipt("gru", spec.PartitionID, spec, bundle,
		object, controllerPrivate, now)
	if err != nil {
		t.Fatal(err)
	}
	reply := customerPreparationReply{Receipt: receipt, Customer: bundle.Customer}
	replyWire, err := protocol.EncodeJSON(reply)
	if err != nil {
		t.Fatal(err)
	}
	publicDER, err := x509.MarshalPKIXPublicKey(controllerPublic)
	if err != nil {
		t.Fatal(err)
	}
	privateDER, err := x509.MarshalPKCS8PrivateKey(recipient)
	if err != nil {
		t.Fatal(err)
	}
	specPath := filepath.Join(directory, "spec.json")
	replyPath := filepath.Join(directory, "reply.json")
	controllerPath := filepath.Join(directory, "controller.pem")
	recipientPath := filepath.Join(directory, "recipient.pem")
	for _, file := range []struct {
		path string
		data []byte
		mode os.FileMode
	}{
		{specPath, specWire, 0o644}, {replyPath, replyWire, 0o644},
		{controllerPath, pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: publicDER}), 0o644},
		{recipientPath, pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: privateDER}), 0o600},
	} {
		if err := os.WriteFile(file.path, file.data, file.mode); err != nil {
			t.Fatal(err)
		}
	}
	return specPath, replyPath, controllerPath, recipientPath, spec, reply,
		customerOpenSigningKeys{recipientSigner: recipientSigner, controller: controllerPrivate, bundle: bundle}
}

func customerOpenArgs(spec, reply, controller, recipient, output string) []string {
	return []string{"open-customer-material", "--spec", spec, "--reply", reply,
		"--controller-key", controller, "--cell", "gru", "--recipient-key", recipient, "--out", output}
}

func (c command) openRotatedCustomerMaterialAt(args []string) error {
	flags := flag.NewFlagSet("open-rotated-customer-material", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	replyPath := flags.String("reply", "", "operator material-credentials JSON reply")
	requestPath := flags.String("request", "", "original credential rotation intent JSON")
	specPath := flags.String("spec", "", "independently retained generation-one material spec JSON")
	controllerPath := flags.String("controller-key", "", "independently pinned controller Ed25519 public key PEM")
	cell := flags.String("cell", "", "expected regional cell")
	recipientPath := flags.String("recipient-key", "", "owner-only rotation recipient X25519 PKCS#8 private key PEM")
	outputPath := flags.String("out", "", "new owner-only JSON output file")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *replyPath == "" || *requestPath == "" || *specPath == "" || *controllerPath == "" ||
		*cell == "" || *recipientPath == "" || *outputPath == "" || !filepath.IsAbs(*outputPath) || flags.NArg() != 0 {
		return errors.New("open-rotated-customer-material requires --reply, --request, --spec, --controller-key, --cell, --recipient-key, and absolute --out")
	}
	specWire, err := c.readBoundedRegular(*specPath, maxCustomerSpecBytes)
	if err != nil {
		return fmt.Errorf("read initial material spec: %w", err)
	}
	var spec managedmaterial.InitialSpec
	if err := protocol.DecodeStrict(specWire, &spec, maxCustomerSpecBytes); err != nil {
		return fmt.Errorf("decode initial material spec: %w", err)
	}
	requestWire, err := c.readBoundedRegular(*requestPath, maxCredentialRequestBytes)
	if err != nil {
		return fmt.Errorf("read credential rotation intent: %w", err)
	}
	var request managedmaterial.CredentialRequest
	if err := protocol.DecodeStrict(requestWire, &request, maxCredentialRequestBytes); err != nil {
		return fmt.Errorf("decode credential rotation intent: %w", err)
	}
	if request.Action != managedmaterial.CredentialRotate {
		return errors.New("credential intent is not a rotation")
	}
	replyWire, err := c.readBoundedRegular(*replyPath, maxCredentialReplyBytes)
	if err != nil {
		return fmt.Errorf("read credential rotation reply: %w", err)
	}
	var reply customerCredentialReply
	if err := protocol.DecodeStrict(replyWire, &reply, maxCredentialReplyBytes); err != nil {
		return fmt.Errorf("decode credential rotation reply: %w", err)
	}
	if reply.Status != "pending" || reply.Credential.Receipt.Customer == nil {
		return errors.New("credential rotation reply has no pending customer token")
	}
	controllerKey, err := readRootPublicKey(*controllerPath)
	if err != nil {
		return fmt.Errorf("read controller trust pin: %w", err)
	}
	if err := managedmaterial.VerifyCredentialReply(reply.Credential, request, controllerKey, *cell); err != nil {
		return fmt.Errorf("verify signed credential rotation reply: %w", err)
	}
	retainedSpecWire, err := protocol.EncodeJSON(reply.Credential.Initial.Spec)
	if err != nil {
		return err
	}
	expectedSpecWire, err := protocol.EncodeJSON(spec)
	if err != nil || !bytes.Equal(retainedSpecWire, expectedSpecWire) {
		return errors.New("retained initial material spec differs from signed receipt")
	}
	recipient, err := managedmaterial.ReadRecipientKey(*recipientPath)
	if err != nil {
		return err
	}
	spec.Recipient = request.Recipient
	material, err := managedmaterial.OpenCustomerEnvelope(spec, *reply.Credential.Receipt.Customer, recipient)
	if err != nil {
		return err
	}
	output, err := protocol.EncodeJSON(material)
	if err != nil {
		return err
	}
	defer clear(output)
	return c.writeNewCustomerMaterial(*outputPath, output)
}

func (c command) writeNewCustomerMaterial(path string, contents []byte) error {
	if err := c.ctx.Err(); err != nil {
		return err
	}
	if len(contents) == 0 {
		return errors.New("customer material output is empty")
	}
	directory := filepath.Dir(path)
	file, err := os.CreateTemp(directory, ".ts-bootstrap-customer-*")
	if err != nil {
		return fmt.Errorf("create customer material temporary file: %w", err)
	}
	temporary := file.Name()
	defer os.Remove(temporary)
	if err := file.Chmod(0o600); err != nil {
		_ = file.Close()
		return err
	}
	if _, err := file.Write(contents); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := c.ctx.Err(); err != nil {
		return err
	}
	if err := os.Link(temporary, path); err != nil {
		return fmt.Errorf("publish customer material without overwrite: %w", err)
	}
	if err := os.Remove(temporary); err != nil {
		_ = os.Remove(path)
		return err
	}
	dir, err := os.Open(directory)
	if err != nil {
		_ = os.Remove(path)
		return err
	}
	defer dir.Close()
	if err := dir.Sync(); err != nil {
		_ = os.Remove(path)
		return err
	}
	return nil
}

