	wire, err := protocol.EncodeJSON(plan)
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "manual-seed-plan.json")
	writeFixture(t, path, wire, 0o600)
	return path, digest(wire)
}

