func identityRekeyTestBroker(t *testing.T) (*natscell.Runtime, jetstream.Stream, natscell.Config) {
	t.Helper()
	directory := filepath.Join(t.TempDir(), "material")
	_, err := bootstrapmaterial.Generate(directory, bootstrapmaterial.Config{Environment: "production", Region: "sa-saopaulo-1", Cell: "gru",
		DeploymentID: entityid.New(), ClusterID: entityid.New(), SubnetCIDR: "10.251.0.0/24", ValidityHours: 48,
		Slots: []bootstrapmaterial.Slot{{Name: "controller-a", PrivateIP: "10.251.0.10"}, {Name: "controller-b", PrivateIP: "10.251.0.11"}, {Name: "controller-c", PrivateIP: "10.251.0.12"}}}, time.Now().UTC())
	if err != nil {
		t.Fatal(err)
	}
	path := func(name string) string { return filepath.Join(directory, name) }
	tlsFiles := natscell.TLSFiles{CAFile: path("ca.pem"), CertFile: path("controller-a-tls-cert.pem"), KeyFile: path("controller-a-tls-key.pem")}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	port := listener.Addr().(*net.TCPAddr).Port
	if err := listener.Close(); err != nil {
		t.Fatal(err)
	}
	cfg := natscell.Config{Cell: "gru", Instance: "controller-a", Replicas: 1, ClientRole: "controller", CredentialsFile: path("controller-a.creds"), TLS: tlsFiles,
		Embedded: &natscell.Embedded{StoreDir: t.TempDir(), Host: "127.0.0.1", Port: port, TLS: tlsFiles, RouteTLS: tlsFiles,
			OperatorJWTFile: path("operator.jwt"), SystemJWTFile: path("system.jwt"), CellJWTFile: path("cell.jwt"),
			SystemCredentialsFile: path("system.creds"), TicketPublicKeyFile: path("ticket.pub"), BrokerIDs: []string{"controller-a"}}}
	runtime, err := natscell.Start(t.Context(), cfg)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = runtime.Close() })
	if err := runtime.Bridge().OpenUntil(1, runtime.InitialCellJWT(), time.Now().Add(time.Minute)); err != nil {
		t.Fatal(err)
	}
	for _, bucket := range []string{"TS_SERVICE_SET", "TS_TRUST_ROOTS", "TS_HOST_STATE"} {
		if _, err := runtime.JetStream().CreateKeyValue(t.Context(), jetstream.KeyValueConfig{Bucket: bucket, Storage: jetstream.FileStorage, Replicas: 1}); err != nil {
			t.Fatal(err)
		}
	}
	stream, err := runtime.JetStream().CreateStream(t.Context(), jetstream.StreamConfig{Name: authority.ControlStreamName,
		Subjects: []string{protocol.ControlStreamSubject()}, Retention: jetstream.LimitsPolicy,
		MaxConsumers: -1, MaxMsgs: -1, MaxBytes: -1, MaxMsgsPerSubject: -1,
		Storage: jetstream.FileStorage, Replicas: 1, DenyDelete: true, DenyPurge: true,
		Metadata: map[string]string{"terrascale-contract": "authority-log-v1"}})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := runtime.JetStream().Publish(t.Context(), protocol.Control("gru", "lease"), identityRekeyOldLease); err != nil {
		t.Fatal(err)
	}
	return runtime, stream, cfg
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func VerifyIdentityReset(envelope trust.Envelope, roots trust.Keyring, target IdentityResetTarget, now time.Time) (IdentityReset, error) {
	if target.Replicas < 1 || target.Replicas > 5 || target.Replicas%2 == 0 {
		return IdentityReset{}, errors.New("identity reset requires an existing odd replica quorum")
	}
	expected := IdentityReset{DeploymentID: target.DeploymentID, Scope: target.Scope, Environment: target.Environment}
	payload, err := trust.VerifyCurrent(envelope, expected.trustScope(), roots, now, identityResetPolicy)
	if err != nil {
		return IdentityReset{}, fmt.Errorf("verify root-signed identity reset: %w", err)
	}
	var reset IdentityReset
	if err := protocol.DecodeStrict(payload, &reset, maxIdentityResetBytes); err != nil {
		return IdentityReset{}, err
	}
	if err := reset.Validate(); err != nil {
		return IdentityReset{}, err
	}
	canonical, err := trust.EncodePayload(reset)
	if err != nil || !bytes.Equal(payload, canonical) {
		return IdentityReset{}, errors.New("identity reset payload must be canonical v1 JSON")
	}
	if reset.OperationID != target.OperationID || reset.DeploymentID != target.DeploymentID ||
		reset.ClusterID != target.ClusterID || reset.Scope != target.Scope || reset.Environment != target.Environment ||
		reset.CheckpointSHA256 != target.CheckpointSHA256 || reset.HostStatePlanSHA256 != target.HostStatePlanSHA256 {
		return IdentityReset{}, trust.ErrScopeMismatch
	}
	return reset, nil
}

// ResetIdentityLease appends a released barrier to the existing immutable log.
// It never deletes history or starts a runtime. Shared records must be replaced
// and read back before the new deployment starts acquiring normal authority.
// The caller must match the verified host plan and observe real writer shutdown.
func ResetIdentityLease(ctx context.Context, js jetstream.JetStream, envelope trust.Envelope,
	roots trust.Keyring, target IdentityResetTarget, now time.Time,
) (uint64, error) {
	reset, err := VerifyIdentityReset(envelope, roots, target, now)
	if err != nil {
		return 0, err
	}
	if js == nil {
		return 0, errors.New("identity reset requires JetStream")
	}
	bounded, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	defer cancel()
	stream, err := js.Stream(bounded, ControlStreamName)
	if err != nil {
		return 0, fmt.Errorf("open existing identity reset stream: %w", err)
	}
	info, err := stream.Info(bounded)
	if err != nil {
		return 0, err
	}
	if err := verifyControlStreamConfig(info.Config, target.Replicas); err != nil {
		return 0, err
	}
	subject := fmt.Sprintf("%s.%s.lease", controlSubjectRoot, reset.Scope)
	barrier, err := identityResetLease(reset, resetDigest(envelope.Payload))
	if err != nil {
		return 0, err
	}
	previous, err := stream.GetLastMsgForSubject(bounded, subject)
	if err != nil {
		return 0, err
	}
	if bytes.Equal(previous.Data, barrier) {
		if previous.Sequence != reset.LastSequence+1 {
			return 0, ErrConflict
		}
		if _, err := verifyCommittedIdentityReset(ctx, js, envelope, roots, target); err != nil {
			return 0, err
		}
		return previous.Sequence, nil
	}
	if info.State.LastSeq != reset.LastSequence || previous.Sequence != reset.PreviousSequence ||
		resetDigest(previous.Data) != reset.PreviousSHA256 {
		return 0, ErrConflict
	}
	if err := verifyIdentityResetGlobalPredecessor(bounded, stream, reset); err != nil {
		return 0, err
	}
	if err := verifyIdentityResetHostInventory(ctx, js, reset, target.Replicas); err != nil {
		return 0, err
	}
	if reset.GlobalLease != nil {
		return publishIdentityResetBatch(ctx, js, stream, reset, envelope, roots, target)
	}
	ack, publishErr := js.PublishMsg(bounded, controlMessage(subject, "lease", reset.OperationID, barrier),
		jetstream.WithExpectLastSequence(reset.LastSequence),
		jetstream.WithExpectLastSequenceForSubject(reset.PreviousSequence, subject))
	if isSequenceConflict(publishErr) {
		return 0, ErrConflict
	}
	// A lost publish reply is resolved only by leader-backed exact readback.
	probe, probeCancel := context.WithTimeout(context.WithoutCancel(ctx), authorityAPITimeout)
	defer probeCancel()
	readInfo, readErr := stream.Info(probe)
	if readErr == nil {
		readErr = verifyControlStreamConfig(readInfo.Config, target.Replicas)
	}
	if readErr != nil {
		return 0, fmt.Errorf("%w: identity reset policy readback: %w", ErrOutcomeUnknown, errors.Join(publishErr, readErr))
	}
	stored, readErr := stream.GetLastMsgForSubject(probe, subject)
	if readErr != nil {
		return 0, fmt.Errorf("%w: identity reset confirmation: %w", ErrOutcomeUnknown, errors.Join(publishErr, readErr))
	}
	if !bytes.Equal(stored.Data, barrier) || publishErr == nil && (ack == nil || stored.Sequence != ack.Sequence) {
		if publishErr != nil && stored.Sequence == reset.PreviousSequence {
			return 0, fmt.Errorf("identity reset publish: %w", publishErr)
		}
		return 0, ErrConflict
	}
	if _, err := verifyCommittedIdentityReset(probe, js, envelope, roots, target); err != nil {
		return 0, fmt.Errorf("%w: committed reset needs current-root recovery authorization: %w", ErrOutcomeUnknown, err)
	}
	return stored.Sequence, nil
}

func verifyIdentityResetHostInventory(ctx context.Context, js jetstream.JetStream, reset IdentityReset, replicas int) error {
	if js == nil {
		return errors.New("identity inventory requires JetStream")
	}
	reviewed := make(map[string]bool, len(reset.Records))
	checked := make(map[string]bool)
	for _, record := range reset.Records {
		if record.Bucket != ControlStreamName && !checked[record.Bucket] {
			if err := checkIdentityBucket(ctx, js, record.Bucket, replicas); err != nil {
				return err
			}
			checked[record.Bucket] = true
		}
		reviewed[identityRecordSubject(record)] = true
	}
	count := 0
	for _, inventory := range [][2]string{
		{ControlStreamName, controlSubjectRoot + "." + reset.Scope + ".host.>"},
		{"KV_TS_HOST_STATE", "$KV.TS_HOST_STATE.>"},
		{"KV_TS_HOST_ENROLLMENT", "$KV.TS_HOST_ENROLLMENT.>"},
	} {
		bounded, cancel := context.WithTimeout(ctx, authorityAPITimeout)
		stream, err := js.Stream(bounded, inventory[0])
		if errors.Is(err, jetstream.ErrStreamNotFound) && inventory[0] != ControlStreamName {
			cancel()
			continue
		}
		if err != nil {
			cancel()
			return err
		}
		info, err := stream.Info(bounded, jetstream.WithSubjectFilter(inventory[1]))
		cancel()
		if err != nil {
			return err
		}
		if inventory[0] == ControlStreamName {
			if err := verifyControlStreamConfig(info.Config, replicas); err != nil {
				return err
			}
		} else if err := checkIdentityBucket(ctx, js, strings.TrimPrefix(inventory[0], "KV_"), replicas); err != nil {
			return err
		}
		if len(info.State.Subjects) > maxIdentityResetRecords {
			return ErrListTooLarge
		}
		for subject := range info.State.Subjects {
			if inventory[0] == ControlStreamName {
				kind, _, _ := strings.Cut(strings.TrimPrefix(subject, controlSubjectRoot+"."+reset.Scope+".host."), ".")
				if HostMutationKind(kind) != MutationRegistration && HostMutationKind(kind) != MutationDesired && HostMutationKind(kind) != MutationRetirement {
					continue
				}
			}
			if key, ok := strings.CutPrefix(subject, "$KV.TS_HOST_STATE."); ok {
				parts := strings.Split(key, ".")
				// Only named namespaces establish foreign-cell ownership. Opaque
				// keys in these cell-local buckets must have explicit root pins.
				if len(parts) >= 2 && slices.Contains([]string{"session", "retired", "retirement-quarantine", "cycle", "report", "desired", "retirement-cutover", "terrabase-format"}, parts[0]) && parts[1] != reset.Scope && natsToken.MatchString(parts[1]) {
					continue
				}
			}
			count++
			if count > maxIdentityResetRecords {
				return ErrListTooLarge
			}
			if !reviewed[subject] {
				return fmt.Errorf("%w: unreviewed host inventory %s", ErrConflict, subject)
			}
		}
	}
	return nil
}

func verifyCommittedIdentityReset(ctx context.Context, js jetstream.JetStream, envelope trust.Envelope,
	roots trust.Keyring, target IdentityResetTarget,
) (IdentityReset, error) {
	bounded, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	defer cancel()
	reset, stream, messages, err := observeIdentityResetCommitment(bounded, js, envelope, roots, target)
	if err != nil {
		return IdentityReset{}, err
	}
	var lifetimeErr error
	for _, msg := range messages {
		if _, err := VerifyIdentityReset(envelope, roots, target, msg.Time); err != nil {
			lifetimeErr = errors.Join(lifetimeErr, err)
		}
	}
	if lifetimeErr == nil {
		return reset, nil
	}
	// A fresh signed authorization is required for an out-of-window commit.
	msg, err := stream.GetLastMsgForSubject(bounded, resetRecoverySubject(reset))
	if err != nil {
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			return IdentityReset{}, lifetimeErr
		}
		return IdentityReset{}, errors.Join(lifetimeErr, err)
	}
	recovery, err := trust.DecodeEnvelope(msg.Data)
	if err != nil {
		return IdentityReset{}, err
	}
	pins, err := resetRecoveryPins(envelope, messages)
	if err != nil {
		return IdentityReset{}, err
	}
	if err := verifyResetRecovery(recovery, roots, reset, pins, msg.Time); err != nil {
		return IdentityReset{}, err
	}
	return reset, nil
}

